-- Vicdogs Perú · Base de datos PostgreSQL
-- Convertido desde el script de MySQL. El esquema coincide con el modelo ACTUAL de la app
-- (incluye Cumpleanos, redes sociales, TipoAgua, Hospedaje, Pesos y Recordatorios).
--
-- Ejecutar sobre una base VACÍA (en Render: la base "vicdogs" ya viene creada).
--   psql "<External Database URL>" -f vicdogs_postgres.sql
-- Después la app arranca sola: crea el usuario admin y no vuelve a sembrar datos
-- porque Servicios y Caninos ya tienen filas.

BEGIN;

CREATE TABLE "Usuarios" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "NombreUsuario" varchar(50) NOT NULL,
  "ClaveHash" varchar(300) NOT NULL,
  "NombreCompleto" varchar(100) NULL
);
CREATE UNIQUE INDEX "IX_Usuarios_NombreUsuario" ON "Usuarios" ("NombreUsuario");

CREATE TABLE "Servicios" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombre" varchar(80) NOT NULL
);

CREATE TABLE "Tutores" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombre" varchar(120) NOT NULL,
  "Telefono" varchar(30) NULL,
  "Cumpleanos" timestamp NULL,
  "Direccion" varchar(200) NULL,
  "Notas" varchar(500) NULL,
  "Instagram" varchar(200) NULL,
  "TikTok" varchar(200) NULL,
  "Facebook" varchar(200) NULL
);

CREATE TABLE "Caninos" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombre" varchar(80) NOT NULL,
  "Sexo" varchar(10) NOT NULL,
  "EdadTexto" varchar(40) NULL,
  "FechaNacimiento" timestamp NULL,
  "Raza" varchar(100) NULL,
  "ServicioId" integer NOT NULL,
  "Distrito" varchar(80) NULL,
  "PesoKg" numeric(6,2) NULL,
  "TipoBano" varchar(30) NULL,
  "AlimentacionTipo" varchar(80) NULL,
  "AlimentacionMarca" varchar(80) NULL,
  "Instagram" varchar(200) NULL,
  "TikTok" varchar(200) NULL,
  "TipoAgua" varchar(30) NULL,
  "HospedajeDesde" timestamp NULL,
  "HospedajeHasta" timestamp NULL,
  "FotoUrl" varchar(200) NULL,
  "Observaciones" varchar(1000) NULL,
  "Activo" boolean NOT NULL DEFAULT TRUE,
  "FechaRegistro" timestamp NOT NULL,
  CONSTRAINT "FK_Caninos_Servicios_ServicioId" FOREIGN KEY ("ServicioId") REFERENCES "Servicios" ("Id") ON DELETE RESTRICT
);
CREATE INDEX "IX_Caninos_Nombre" ON "Caninos" ("Nombre");
CREATE INDEX "IX_Caninos_ServicioId" ON "Caninos" ("ServicioId");

CREATE TABLE "CaninoTutores" (
  "CaninoId" integer NOT NULL,
  "TutorId" integer NOT NULL,
  PRIMARY KEY ("CaninoId", "TutorId"),
  CONSTRAINT "FK_CaninoTutores_Caninos_CaninoId" FOREIGN KEY ("CaninoId") REFERENCES "Caninos" ("Id") ON DELETE CASCADE,
  CONSTRAINT "FK_CaninoTutores_Tutores_TutorId" FOREIGN KEY ("TutorId") REFERENCES "Tutores" ("Id") ON DELETE CASCADE
);
CREATE INDEX "IX_CaninoTutores_TutorId" ON "CaninoTutores" ("TutorId");

CREATE TABLE "Vacunas" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CaninoId" integer NOT NULL,
  "Tipo" varchar(40) NOT NULL,
  "FechaAplicada" timestamp NULL,
  "FechaProxima" timestamp NULL,
  "Observacion" varchar(300) NULL,
  CONSTRAINT "FK_Vacunas_Caninos_CaninoId" FOREIGN KEY ("CaninoId") REFERENCES "Caninos" ("Id") ON DELETE CASCADE
);
CREATE INDEX "IX_Vacunas_CaninoId" ON "Vacunas" ("CaninoId");

CREATE TABLE "Antipulgas" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CaninoId" integer NOT NULL,
  "Fecha" timestamp NULL,
  "Marca" varchar(80) NULL,
  "Meses" integer NULL,
  CONSTRAINT "FK_Antipulgas_Caninos_CaninoId" FOREIGN KEY ("CaninoId") REFERENCES "Caninos" ("Id") ON DELETE CASCADE
);
CREATE INDEX "IX_Antipulgas_CaninoId" ON "Antipulgas" ("CaninoId");

CREATE TABLE "Desparasitaciones" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CaninoId" integer NOT NULL,
  "Fecha" timestamp NOT NULL,
  "Producto" varchar(80) NULL,
  CONSTRAINT "FK_Desparasitaciones_Caninos_CaninoId" FOREIGN KEY ("CaninoId") REFERENCES "Caninos" ("Id") ON DELETE CASCADE
);
CREATE INDEX "IX_Desparasitaciones_CaninoId" ON "Desparasitaciones" ("CaninoId");

CREATE TABLE "Pesos" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CaninoId" integer NOT NULL,
  "Fecha" timestamp NOT NULL,
  "PesoKg" numeric(6,2) NOT NULL,
  "Nota" varchar(200) NULL,
  CONSTRAINT "FK_Pesos_Caninos_CaninoId" FOREIGN KEY ("CaninoId") REFERENCES "Caninos" ("Id") ON DELETE CASCADE
);
CREATE INDEX "IX_Pesos_CaninoId" ON "Pesos" ("CaninoId");

CREATE TABLE "Recordatorios" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Titulo" varchar(120) NOT NULL,
  "Notas" varchar(300) NULL,
  "Frecuencia" varchar(10) NOT NULL,
  "DiaMes" integer NULL,
  "DiaSemana" integer NULL,
  "Fecha" timestamp NULL,
  "AvisarDiasAntes" integer NOT NULL,
  "Activo" boolean NOT NULL,
  "HechoFecha" timestamp NULL
);

-- ===== Datos iniciales =====








-- Los Id de Servicios, Tutores y Caninos se insertaron a mano: se reinician las secuencias
-- para que los próximos registros que cree la app no choquen con ellos.
SELECT setval(pg_get_serial_sequence('"Servicios"', 'Id'), COALESCE((SELECT MAX("Id") FROM "Servicios"), 1));
SELECT setval(pg_get_serial_sequence('"Tutores"', 'Id'),   COALESCE((SELECT MAX("Id") FROM "Tutores"), 1));
SELECT setval(pg_get_serial_sequence('"Caninos"', 'Id'),   COALESCE((SELECT MAX("Id") FROM "Caninos"), 1));

COMMIT;

-- Verificación rápida
SELECT (SELECT COUNT(*) FROM "Caninos") AS caninos,
       (SELECT COUNT(*) FROM "Tutores") AS tutores,
       (SELECT COUNT(*) FROM "Vacunas") AS vacunas;
